package main

import (
	"fmt"
	"image"
	"image/png"
	"os"
	"strconv"
)

func main() {
	f, _ := os.Open(os.Args[1])
	img, err := png.Decode(f)
	if err != nil {
		panic(err)
	}
	b := img.Bounds()
	sx, sy := 4, 8
	if len(os.Args) > 2 {
		sx, _ = strconv.Atoi(os.Args[2])
		sy, _ = strconv.Atoi(os.Args[3])
	}
	fmt.Printf("%T %v\n", img, b)
	// color histogram
	hist := map[[4]uint8]int{}
	for y := b.Min.Y; y < b.Max.Y; y++ {
		for x := b.Min.X; x < b.Max.X; x++ {
			r, g, bb, a := img.At(x, y).RGBA()
			hist[[4]uint8{uint8(r >> 8), uint8(g >> 8), uint8(bb >> 8), uint8(a >> 8)}]++
		}
	}
	type kv struct {
		k [4]uint8
		v int
	}
	var kvs []kv
	for k, v := range hist {
		kvs = append(kvs, kv{k, v})
	}
	for i := range kvs {
		for j := i + 1; j < len(kvs); j++ {
			if kvs[j].v > kvs[i].v {
				kvs[i], kvs[j] = kvs[j], kvs[i]
			}
		}
	}
	for i, kv := range kvs {
		if i > 15 {
			break
		}
		fmt.Println(kv.k, kv.v)
	}
	fmt.Println("ncolors", len(kvs))
	for y := b.Min.Y; y < b.Max.Y; y += sy {
		line := []byte{}
		for x := b.Min.X; x < b.Max.X; x += sx {
			// darkest in block
			minv := 1 << 30
			for yy := y; yy < y+sy && yy < b.Max.Y; yy++ {
				for xx := x; xx < x+sx && xx < b.Max.X; xx++ {
					r, g, bb, a := img.At(xx, yy).RGBA()
					_ = a
					v := int(r+g+bb) / 3
					if a == 0 {
						v = 65535
					}
					if v < minv {
						minv = v
					}
				}
			}
			c := byte(' ')
			switch {
			case minv < 16000:
				c = '#'
			case minv < 40000:
				c = '+'
			case minv < 60000:
				c = '.'
			}
			line = append(line, c)
		}
		fmt.Println(string(line))
	}
}
