package main

// prints, for each column, the topmost row of a given color (or any non-transparent), for a row band
import (
	"fmt"
	"image/png"
	"os"
	"strconv"
)

func main() {
	f, _ := os.Open(os.Args[1])
	img, err := png.Decode(f)
	if err != nil {
		panic(err)
	}
	mode := os.Args[2]
	b := img.Bounds()
	switch mode {
	case "blue": // per column: count & top of fill color pixels
		for x := b.Min.X; x < b.Max.X; x++ {
			top, cnt := -1, 0
			for y := b.Min.Y; y < b.Max.Y; y++ {
				r, g, bb, a := img.At(x, y).RGBA()
				if a > 0 && r>>8 < 60 && g>>8 > 60 && bb>>8 > 150 {
					if top < 0 {
						top = y
					}
					cnt++
				}
			}
			if cnt > 0 {
				fmt.Printf("x=%d top=%d cnt=%d\n", x, top, cnt)
			}
		}
	case "pix": // dump region x0 y0 x1 y1 as hex alpha
		x0, _ := strconv.Atoi(os.Args[3])
		y0, _ := strconv.Atoi(os.Args[4])
		x1, _ := strconv.Atoi(os.Args[5])
		y1, _ := strconv.Atoi(os.Args[6])
		for y := y0; y < y1; y++ {
			fmt.Printf("%3d ", y)
			for x := x0; x < x1; x++ {
				r, g, bb, a := img.At(x, y).RGBA()
				_ = r
				_ = g
				_ = bb
				fmt.Printf("%02x", a>>8)
			}
			fmt.Println()
		}
	case "rgba":
		x0, _ := strconv.Atoi(os.Args[3])
		y0, _ := strconv.Atoi(os.Args[4])
		x1, _ := strconv.Atoi(os.Args[5])
		y1, _ := strconv.Atoi(os.Args[6])
		for y := y0; y < y1; y++ {
			for x := x0; x < x1; x++ {
				c := img.At(x, y)
				fmt.Printf("(%d,%d) %v\n", x, y, c)
			}
		}
	}
}
EOF
