package main

import (
	"fmt"
	"image/png"
	"os"
)

func main() {
	f1, _ := os.Open(os.Args[1])
	a, err := png.Decode(f1)
	if err != nil {
		panic(err)
	}
	f2, _ := os.Open(os.Args[2])
	b, err := png.Decode(f2)
	if err != nil {
		panic(err)
	}
	if a.Bounds() != b.Bounds() {
		fmt.Println("bounds differ", a.Bounds(), b.Bounds())
		return
	}
	n := 0
	minx, miny, maxx, maxy := 1<<30, 1<<30, -1, -1
	for y := a.Bounds().Min.Y; y < a.Bounds().Max.Y; y++ {
		for x := a.Bounds().Min.X; x < a.Bounds().Max.X; x++ {
			r1, g1, b1, a1 := a.At(x, y).RGBA()
			r2, g2, b2, a2 := b.At(x, y).RGBA()
			if r1 != r2 || g1 != g2 || b1 != b2 || a1 != a2 {
				n++
				if x < minx {
					minx = x
				}
				if y < miny {
					miny = y
				}
				if x > maxx {
					maxx = x
				}
				if y > maxy {
					maxy = y
				}
				if n <= 10 {
					fmt.Println(x, y, a.At(x, y), b.At(x, y))
				}
			}
		}
	}
	fmt.Println("diff pixels", n, "bbox", minx, miny, maxx, maxy)
}
