package main

// segment glyphs in a horizontal text band [y0,y1) and print them as ascii art side by side with x positions
import (
	"fmt"
	"image/png"
	"os"
	"strconv"
)

func main() {
	f, _ := os.Open(os.Args[1])
	img, err := png.Decode(f)
	if err != nil {
		panic(err)
	}
	y0, _ := strconv.Atoi(os.Args[2])
	y1, _ := strconv.Atoi(os.Args[3])
	x0, x1 := img.Bounds().Min.X, img.Bounds().Max.X
	if len(os.Args) > 5 {
		x0, _ = strconv.Atoi(os.Args[4])
		x1, _ = strconv.Atoi(os.Args[5])
	}
	thr := uint32(40)
	col := func(x int) bool {
		for y := y0; y < y1; y++ {
			_, _, _, a := img.At(x, y).RGBA()
			if a>>8 > thr {
				return true
			}
		}
		return false
	}
	// group columns into words (gap >= 4 px)
	x := x0
	for x < x1 {
		for x < x1 && !col(x) {
			x++
		}
		if x >= x1 {
			break
		}
		start := x
		gap := 0
		end := x
		for x < x1 {
			if col(x) {
				gap = 0
				end = x
			} else {
				gap++
				if gap >= 6 {
					break
				}
			}
			x++
		}
		fmt.Printf("word x=%d..%d\n", start, end)
		for y := y0; y < y1; y++ {
			line := ""
			for xx := start; xx <= end; xx++ {
				_, _, _, a := img.At(xx, y).RGBA()
				if a>>8 > 128 {
					line += "#"
				} else if a>>8 > thr {
					line += "+"
				} else {
					line += " "
				}
			}
			fmt.Println("  " + line)
		}
	}
}
EOF
