	"fmt"
	"image/png"
	"os"
	"strconv"
)

// prints luminance-based ascii (ignores alpha, treats transparent as black)
func main() {
	f, _ := os.Open(os.Args[1])
	img, err := png.Decode(f)
	if err != nil {
		panic(err)
	}
	x0, _ := strconv.Atoi(os.Args[2])
	y0, _ := strconv.Atoi(os.Args[3])
	x1, _ := strconv.Atoi(os.Args[4])
	y1, _ := strconv.Atoi(os.Args[5])
	chars := " .:-=+*#%@"
	for y := y0; y < y1; y++ {
		line := fmt.Sprintf("%4d ", y)
		for x := x0; x < x1; x++ {
			r, g, b, _ := img.At(x, y).RGBA()
			l := (r*299 + g*587 + b*114) / 1000 >> 8
			idx := int(l) * (len(chars) - 1) / 255
			line += string(chars[idx])
		}
		fmt.Println(line)
	}
}
EOF
