package main

// find columns which have a dashed pattern: count rows where pixel differs from pixel 2 rows above significantly in alpha or color
import (
	"fmt"
	"image"
	"image/png"
	"os"
)

func main() {
	f, _ := os.Open(os.Args[1])
	im, _ := png.Decode(f)
	img := im.(*image.NRGBA)
	b := img.Bounds()
	for x := 0; x < b.Max.X; x++ {
		n := 0
		for y := 4; y < b.Max.Y; y++ {
			c := img.NRGBAAt(x, y)
			l := img.NRGBAAt(x-1, y)
			r := img.NRGBAAt(x+1, y)
			_ = r
			// marker pixel: grayish with alpha>=100 and different from left neighbor or right neighbor
			if c.A >= 60 && c != l && int(c.R)+10 > int(c.B)/2 && c.R > 50 {
				n++
			}
		}
		if n > 80 {
			fmt.Println(x, n)
		}
	}
}
