package main

import (
	"fmt"
	"image"
	"image/png"
	"os"
)

func isGray(c [4]uint8) bool { return c[3] > 30 && c[0] > 150 && c[0] == c[1] && c[1] == c[2] }

func main() {
	f, _ := os.Open(os.Args[1])
	im, _ := png.Decode(f)
	img := im.(*image.NRGBA)
	b := img.Bounds()
	W, H := b.Max.X, b.Max.Y
	at := func(x, y int) [4]uint8 {
		if x < 0 || y < 0 || x >= W || y >= H {
			return [4]uint8{}
		}
		c := img.NRGBAAt(x, y)
		return [4]uint8{c.R, c.G, c.B, c.A}
	}
	// find right axis: rightmost column with many gray alpha-128 pixels
	axisX := -1
	for x := W - 1; x >= 0; x-- {
		n := 0
		for y := 0; y < H; y++ {
			if c := at(x, y); c == [4]uint8{179, 179, 179, 128} {
				n++
			}
		}
		if n > H/3 {
			axisX = x
			break
		}
	}
	// y ticks: rows where pixels at axisX+3 are gray
	var yt []float64
	for y := 0; y < H; y++ {
		c := at(axisX+3, y)
		if isGray(c) {
			yt = append(yt, float64(y)+float64(c[3])/255)
		}
	}
	fmt.Println("W", W, "H", H, "right axis x", axisX)
	fmt.Println("y tick rows (with alpha frac):", yt)
	// x axis: find lowest row with long gray run
	axisY := -1
	for y := H - 1; y >= 0; y-- {
		n := 0
		for x := 0; x < W; x++ {
			if c := at(x, y); isGray(c) {
				n++
			}
		}
		if n > W/3 {
			axisY = y
			break
		}
	}
	var xt []int
	for x := 0; x < W; x++ {
		if isGray(at(x, axisY+3)) {
			xt = append(xt, x)
		}
	}
	fmt.Println("x axis y", axisY, "x tick cols:", xt)
}
EOF
