package term

import (
	"os"
	"syscall"
	"unsafe"
)

// ioctl performs a raw ioctl system call on the given file descriptor.
func ioctl(fd uintptr, req uintptr, arg unsafe.Pointer) error {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, req, uintptr(arg))
	if errno != 0 {
		return errno
	}
	return nil
}

// IsTerminal reports whether the given file refers to a terminal.
func IsTerminal(f *os.File) bool {
	var t syscall.Termios
	return ioctl(f.Fd(), syscall.TCGETS, unsafe.Pointer(&t)) == nil
}

type rawState struct {
	fd  uintptr
	old syscall.Termios
}

// makeRaw switches the terminal attached to fd into raw mode and returns
// the previous state so it can be restored later.
func makeRaw(fd uintptr) (*rawState, error) {
	var t syscall.Termios
	if err := ioctl(fd, syscall.TCGETS, unsafe.Pointer(&t)); err != nil {
		return nil, err
	}
	st := &rawState{fd: fd, old: t}
	t.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP |
		syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	t.Oflag &^= syscall.OPOST
	t.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	t.Cflag &^= syscall.CSIZE | syscall.PARENB
	t.Cflag |= syscall.CS8
	t.Cc[syscall.VMIN] = 1
	t.Cc[syscall.VTIME] = 0
	if err := ioctl(fd, syscall.TCSETS, unsafe.Pointer(&t)); err != nil {
		return nil, err
	}
	return st, nil
}

func (s *rawState) restore() {
	if s == nil {
		return
	}
	_ = ioctl(s.fd, syscall.TCSETS, unsafe.Pointer(&s.old))
}

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

// getWinsize returns the window size of the terminal attached to stdout.
func getWinsize() (winsize, error) {
	var ws winsize
	err := ioctl(os.Stdout.Fd(), syscall.TIOCGWINSZ, unsafe.Pointer(&ws))
	return ws, err
}

// Rows returns the number of text rows of the terminal attached to stdout.
func Rows() (int, error) {
	ws, err := getWinsize()
	if err != nil {
		return 0, err
	}
	return int(ws.Row), nil
}
