package term

import (
	"os"
	"strings"
)

var (
	// ITerm is true when running inside iTerm2.
	ITerm bool
	// Kitty is true when the terminal answered the kitty graphics query.
	Kitty bool
	// Sixel is true when the terminal advertises DRCS sixel graphics.
	Sixel bool
)

const queryBufSize = 200

func init() {
	if os.Getenv("TERM_PROGRAM") == "iTerm.app" {
		ITerm = true
		return
	}
	Kitty = detectKitty()
	Sixel = detectSixel()
}

// HasGraphics reports whether any supported image protocol is available.
func HasGraphics() bool {
	return ITerm || Kitty || Sixel
}

// readOnce performs a single read of the terminal answer.
func readOnce() string {
	buf := make([]byte, queryBufSize)
	n, err := os.Stdout.Read(buf)
	if err != nil || n <= 0 {
		return ""
	}
	return string(buf[:n])
}

func detectKitty() bool {
	st, err := makeRaw(os.Stdout.Fd())
	if err != nil {
		return false
	}
	defer st.restore()
	if _, err := os.Stdout.WriteString("\033_Gi=1,a=q,t=d,f=24\033\\"); err != nil {
		return false
	}
	resp := readOnce()
	return strings.Contains(resp, "_Gi=1")
}

var sixelClasses = map[string]bool{
	"\033[?62": true,
	"\033[?63": true,
	"\033[?64": true,
	"\033[?65": true,
}

func detectSixel() bool {
	st, rawErr := makeRaw(os.Stdout.Fd())
	os.Stdout.WriteString("\033[c")
	if rawErr != nil {
		return false
	}
	defer st.restore()
	resp := readOnce()
	if strings.HasPrefix(resp, "\033[?1;2;4c") {
		return true
	}
	attrs := strings.Split(resp, ";")
	if !sixelClasses[attrs[0]] {
		return false
	}
	for _, a := range attrs[1:] {
		if a == "4" {
			return true
		}
	}
	return false
}
