package term

import (
	"errors"
	"fmt"
	"os"
	"sync"
)

// WinSize describes the drawable area of the terminal.
type WinSize struct {
	Row, Col      int
	Width, Height int
}

var errCellSize = errors.New("cannot get terminal cell size")

var (
	cellOnce            sync.Once
	cellW, cellH        float64
	pxOnce              sync.Once
	pxW, pxH            int
	cellErr, pxErr      error
)

// itermCellSize asks iTerm2 for the size of a character cell in pixels.
func itermCellSize() (w, h float64, err error) {
	cellOnce.Do(func() {
		st, e := makeRaw(os.Stdout.Fd())
		if e == nil {
			defer st.restore()
		}
		os.Stdout.WriteString("\033]1337;ReportCellSize\a")
		fmt.Fscanf(os.Stdout, "\033]1337;ReportCellSize=%f;%f\033\\", &cellH, &cellW)
		if cellH == 0 && cellW == 0 {
			cellErr = errCellSize
		}
	})
	return cellW, cellH, cellErr
}

// pixelSize asks the terminal for its text area size in pixels.
func pixelSize() (w, h int, err error) {
	pxOnce.Do(func() {
		st, e := makeRaw(os.Stdout.Fd())
		if e == nil {
			defer st.restore()
		}
		os.Stdout.WriteString("\033[14t")
		fmt.Fscanf(os.Stdout, "\033[4;%d;%dt", &pxH, &pxW)
		if pxH <= 0 || pxW <= 0 {
			pxErr = errCellSize
		}
	})
	return pxW, pxH, pxErr
}

// Size returns the size of the terminal in rows/cols and pixels.
func Size() (WinSize, error) {
	ws, err := getWinsize()
	if err != nil {
		return WinSize{}, err
	}
	rows, cols := int(ws.Row), int(ws.Col)
	if ITerm {
		cw, ch, err := itermCellSize()
		if err != nil {
			return WinSize{}, err
		}
		return WinSize{
			Row:    rows,
			Col:    cols,
			Width:  cols * int(cw),
			Height: rows * int(ch),
		}, nil
	}
	w, h, err := pixelSize()
	if err != nil {
		return WinSize{}, err
	}
	cellWidth := w / (cols - 1)
	cellHeight := h / (rows - 1)
	return WinSize{
		Row:    rows,
		Col:    cols,
		Width:  cellWidth * (cols - 1),
		Height: cellHeight * (rows - 1),
	}, nil
}
EOF
echo ok"}

