package term

import (
	"bytes"
	"encoding/base64"
	"fmt"
	"image/png"
	"io"
	"os"

	"jplot/term/sixel"
)

// ImageWriter streams an encoded PNG image to the terminal using the
// detected graphics protocol.
type ImageWriter struct {
	width, height int
	started       bool
	enc           io.WriteCloser
	buf           *bytes.Buffer
}

// NewImageWriter returns a writer that displays the PNG data written to it.
func NewImageWriter(width, height int) *ImageWriter {
	return &ImageWriter{width: width, height: height}
}

var kittyID = 1

func (w *ImageWriter) start() {
	if w.started {
		return
	}
	w.started = true
	switch {
	case ITerm:
		fmt.Fprintf(os.Stdout, "\033]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:", w.width, w.height)
		w.enc = base64.NewEncoder(base64.StdEncoding, os.Stdout)
	case Kitty:
		kittyID = 3 - kittyID
		fmt.Fprintf(os.Stdout, "\033_Ga=T,f=100,t=d,i=%d,X=0,Y=0,q=2;", kittyID)
		w.enc = base64.NewEncoder(base64.StdEncoding, os.Stdout)
	default:
		w.buf = &bytes.Buffer{}
	}
}

func (w *ImageWriter) Write(p []byte) (int, error) {
	w.start()
	if w.buf != nil {
		return w.buf.Write(p)
	}
	return w.enc.Write(p)
}

var kittyShown bool

// Close terminates the image escape sequence.
func (w *ImageWriter) Close() error {
	w.start()
	switch {
	case ITerm:
		// The encoder is intentionally not flushed.
		os.Stdout.WriteString("\a")
	case Kitty:
		w.enc.Close()
		os.Stdout.WriteString("\033\\")
		if kittyShown {
			fmt.Fprintf(os.Stdout, "\033_Ga=d,d=i,i=%d,q=2\033\\", 3-kittyID)
		}
		kittyShown = true
	default:
		img, err := png.Decode(bytes.NewReader(w.buf.Bytes()))
		if err != nil {
			return err
		}
		return sixel.Encode(os.Stdout, img)
	}
	return nil
}
EOF
echo ok"}

