						v |= 1 << uint(k)
					}
				}
				row[x] = v
				if v != 0 {
					last = x
				}
			}
			if !first {
				bw.WriteByte('$')
			}
			first = false
			fmt.Fprintf(bw, "#%d", n)
			writeRuns(bw, row[:last+1])
		}
		bw.WriteByte('-')
	}
	bw.WriteString("\033\\")
	return bw.Flush()
}

func writeRuns(bw *bufio.Writer, row []byte) {
	for i := 0; i < len(row); {
		j := i
		for j < len(row) && row[j] == row[i] {
			j++
		}
		n := j - i
		ch := row[i] + 63
		for n > 255 {
			fmt.Fprintf(bw, "!255%c", ch)
			n -= 255
		}
		if n >= 4 {
			fmt.Fprintf(bw, "!%d%c", n, ch)
		} else {
			for k := 0; k < n; k++ {
				bw.WriteByte(ch)
			}
		}
		i = j
	}
}

func nearest(p []rgb, c rgb) int {
	best, bd := 0, -1
	for i, q := range p {
		dr := int(q.r) - int(c.r)
		dg := int(q.g) - int(c.g)
		db := int(q.b) - int(c.b)
		d := dr*dr + dg*dg + db*db
		if bd < 0 || d < bd {
			best, bd = i, d
		}
	}
	return best
}

type entry struct {
	c rgb
	n int
}

type box struct{ entries []entry }

func (b *box) span() (int, int) {
	var lo, hi [3]int
	for i := range lo {
		lo[i], hi[i] = 255, 0
	}
	for _, e := range b.entries {
		v := [3]int{int(e.c.r), int(e.c.g), int(e.c.b)}
		for i := range v {
			if v[i] < lo[i] {
				lo[i] = v[i]
			}
			if v[i] > hi[i] {
				hi[i] = v[i]
			}
		}
	}
	axis, s := 0, -1
	for i := range lo {
		if hi[i]-lo[i] > s {
			axis, s = i, hi[i]-lo[i]
		}
	}
	return axis, s
}

func (b *box) mean() rgb {
	var r, g, bl, n int
	for _, e := range b.entries {
		r += int(e.c.r) * e.n
		g += int(e.c.g) * e.n
		bl += int(e.c.b) * e.n
		n += e.n
	}
	if n == 0 {
		return rgb{}
	}
	return rgb{uint8(r / n), uint8(g / n), uint8(bl / n)}
}

// quantize reduces the given color histogram to at most max colors using
// a median cut.
func quantize(counts map[rgb]int, max int) []rgb {
	entries := make([]entry, 0, len(counts))
	for c, n := range counts {
		entries = append(entries, entry{c, n})
	}
	sort.Slice(entries, func(i, j int) bool {
		a, b := entries[i].c, entries[j].c
		if a.r != b.r {
			return a.r < b.r
		}
		if a.g != b.g {
			return a.g < b.g
		}
		return a.b < b.b
	})
	if len(entries) <= max {
		p := make([]rgb, len(entries))
		for i, e := range entries {
			p[i] = e.c
		}
		if len(p) == 0 {
			p = append(p, rgb{})
		}
		return p
	}
	boxes := []*box{{entries: entries}}
	for len(boxes) < max {
		bi, bs, ba := -1, 0, 0
		for i, b := range boxes {
			if len(b.entries) < 2 {
				continue
			}
			a, s := b.span()
			if s > bs {
				bi, bs, ba = i, s, a
			}
		}
		if bi < 0 {
			break
		}
		b := boxes[bi]
		sort.Slice(b.entries, func(i, j int) bool {
			x, y := b.entries[i].c, b.entries[j].c
			switch ba {
			case 0:
				return x.r < y.r
			case 1:
				return x.g < y.g
			}
			return x.b < y.b
		})
		total := 0
		for _, e := range b.entries {
			total += e.n
		}
		acc, cut := 0, 1
		for i, e := range b.entries {
			acc += e.n
			if acc*2 >= total {
				cut = i + 1
				break
			}
		}
		if cut >= len(b.entries) {
			cut = len(b.entries) - 1
		}
		left := &box{entries: append([]entry(nil), b.entries[:cut]...)}
		right := &box{entries: append([]entry(nil), b.entries[cut:]...)}
		boxes[bi] = left
		boxes = append(boxes, right)
	}
	p := make([]rgb, len(boxes))
	for i, b := range boxes {
		p[i] = b.mean()
	}
	return p
}
