// Package sixel implements a small DEC sixel image encoder.
package sixel

import (
	"bufio"
	"fmt"
	"image"
	"io"
	"sort"
)

const maxColors = 255

type rgb struct{ r, g, b uint8 }

// Encode writes img to w as a sixel sequence.
func Encode(w io.Writer, img image.Image) error {
	b := img.Bounds()
	width, height := b.Dx(), b.Dy()
	bw := bufio.NewWriter(w)

	// Collect the (premultiplied) colors of all visible pixels.
	pix := make([]int, width*height) // palette index + 1, 0 means transparent
	counts := map[rgb]int{}
	cols := make([]rgb, width*height)
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			r, g, bb, a := img.At(b.Min.X+x, b.Min.Y+y).RGBA()
			if a == 0 {
				continue
			}
			c := rgb{uint8(r >> 8), uint8(g >> 8), uint8(bb >> 8)}
			cols[y*width+x] = c
			pix[y*width+x] = -1
			counts[c]++
		}
	}
	palette := quantize(counts, maxColors)
	lookup := map[rgb]int{}
	for i := range pix {
		if pix[i] == 0 {
			continue
		}
		c := cols[i]
		idx, ok := lookup[c]
		if !ok {
			idx = nearest(palette, c) + 1
			lookup[c] = idx
		}
		pix[i] = idx
	}

	bw.WriteString("\033P0;0;8q\"1;1")
	for i, c := range palette {
		fmt.Fprintf(bw, "#%d;2;%d;%d;%d", i+1, int(c.r)*100/255, int(c.g)*100/255, int(c.b)*100/255)
	}
	first := true
	row := make([]byte, width)
	for z := 0; z < height/6; z++ {
		used := make([]bool, len(palette)+1)
		if z == 0 {
			for i := range used {
				used[i] = true
			}
		} else {
			for y := z * 6; y < z*6+6; y++ {
				for x := 0; x < width; x++ {
					used[pix[y*width+x]] = true
				}
			}
		}
		for n := 1; n <= len(palette); n++ {
			if !used[n] {
				continue
			}
			last := -1
			for x := 0; x < width; x++ {
				var v byte
				for k := 0; k < 6; k++ {
					if pix[(z*6+k)*width+x] == n {
						v |= 1 << uint(k)
					}
				}
				row[x] = v
				if v != 0 {
					last = x
				}
			}
			if !first {
				bw.WriteByte('$')
			}
			first = false
			fmt.Fprintf(bw, "#%d", n)
			writeRuns(bw, row[:last+1])
		}
		bw.WriteByte('-')
	}
	bw.WriteString("\033\\")
	return bw.Flush()
}

func writeRuns(bw *bufio.Writer, row []byte) {
	for i := 0; i < len(row); {
		j := i
		for j < len(row) && row[j] == row[i] {
			j++
		}
		n := j - i
		ch := row[i] + 63
		for n > 255 {
			fmt.Fprintf(bw, "!255%c", ch)
			n -= 255
		}
		if n >= 4 {
			fmt.Fprintf(bw, "!%d%c", n, ch)
		} else {
			for k := 0; k < n; k++ {
				bw.WriteByte(ch)
			}
		}
		i = j
	}
}

func nearest(p []rgb, c rgb) int {
	best, bd := 0, -1
	for i, q := range p {
		dr := int(q.r) - int(c.r)
		dg := int(q.g) - int(c.g)
		db := int(q.b) - int(c.b)
		d := dr*dr + dg*dg + db*db
		if bd < 0 || d < bd {
			best, bd = i, d
		}
	}
	return best
}

type entry struct {
	c rgb
	n int
}

type box struct{ entries []entry }

func (b *box) span() (int, int) {
	var lo, hi [3]int
