			}
			if v[i] > hi[i] {
				hi[i] = v[i]
			}
		}
	}
	axis, s := 0, -1
	for i := range lo {
		if hi[i]-lo[i] > s {
			axis, s = i, hi[i]-lo[i]
		}
	}
	return axis, s
