package data

import (
	"fmt"
	"strings"
)

// splitPath splits a field path into its keys. An empty segment which is
// not the last one designates a key named ".".
func splitPath(path string) []string {
	parts := strings.Split(path, ".")
	for i := 0; i < len(parts)-1; i++ {
		if parts[i] == "" {
			parts[i] = "."
		}
	}
	return parts
}

func lookup(doc interface{}, path string) (interface{}, error) {
	if path == "." {
		return doc, nil
	}
	v := doc
	for _, key := range splitPath(path) {
		m, ok := v.(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("%s is not an object. %v", key, m)
		}
		if v, ok = m[key]; !ok {
			return nil, fmt.Errorf("%s does not exist.", key)
		}
	}
	return v, nil
}

// getValue extracts the numeric value designated by path in doc.
func getValue(doc interface{}, path string) (float64, error) {
	v, err := lookup(doc, path)
	if err != nil {
		return 0, fmt.Errorf("cannot get %s: %v", path, err)
	}
	f, ok := v.(float64)
	if !ok {
		return 0, fmt.Errorf("invalid type %s: %T", path, v)
	}
	return f, nil
}
