package data

import (
	"sync"
)

// Points stores the last values of every field.
type Points struct {
	mu     sync.Mutex
	steps  int
	specs  []Spec
	values map[string][]float64
	last   map[string]float64
	seen   map[string]bool

	onError func(error)
	done    chan struct{}
	closer  func()
	once    sync.Once
}

func newPoints(specs []Spec, steps int, onError func(error)) *Points {
	return &Points{
		steps:   steps,
		specs:   specs,
		values:  map[string][]float64{},
		last:    map[string]float64{},
		seen:    map[string]bool{},
		onError: onError,
		done:    make(chan struct{}),
	}
}

// Done is closed once the data source is exhausted.
func (p *Points) Done() <-chan struct{} {
	return p.done
}

func (p *Points) finish() {
	p.once.Do(func() { close(p.done) })
}

// Close stops the data source when possible.
func (p *Points) Close() {
	if p.closer != nil {
		p.closer()
	}
}

// push records a new document.
func (p *Points) push(doc interface{}) error {
	type kv struct {
		f Field
		v float64
	}
	var vals []kv
	for _, spec := range p.specs {
		for _, f := range spec.Fields {
			v, err := getValue(doc, f.Name)
			if err != nil {
				return err
			}
			vals = append(vals, kv{f, v})
		}
	}
	p.mu.Lock()
	defer p.mu.Unlock()
	for _, e := range vals {
		v := e.v
		if e.f.Counter {
			prev, ok := p.last[e.f.ID]
			p.last[e.f.ID] = v
			if !ok || v < prev {
				v = 0
			} else {
				v -= prev
			}
		}
		buf := append(p.values[e.f.ID], v)
		if p.steps >= 0 && len(buf) > p.steps {
			buf = buf[len(buf)-p.steps:]
		}
		p.values[e.f.ID] = buf
	}
	return nil
}

// Get returns the last values of the field identified by id. The result
// always holds steps values, older values are zero.
func (p *Points) Get(id string) []float64 {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.getLocked(id)
}

func (p *Points) getLocked(id string) []float64 {
	out := make([]float64, p.steps)
	vals := p.values[id]
	copy(out[len(out)-len(vals):], vals)
	return out
}
