package main

import (
	"flag"
	"fmt"
	"os"
	"os/signal"
	"strings"
	"sync"
	"syscall"
	"time"

	"jplot/data"
	"jplot/graph"
	"jplot/term"
)

func usage() {
	out := flag.CommandLine.Output()
	fmt.Fprintf(out, "Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:\n")
	fmt.Fprintf(out, "\nOPTIONS:\n")
	flag.PrintDefaults()
	fmt.Fprintf(out, "\nFIELD_SPEC: [<option>[,<option>...]:]path\n")
	fmt.Fprintf(out, "  option:\n")
	fmt.Fprintf(out, "    - counter: Computes the difference with the last value. The value must increase monotonically.\n")
	fmt.Fprintf(out, "    - marker: When the value is none-zero, a vertical line is drawn.\n")
	fmt.Fprintf(out, "  path:\n")
	fmt.Fprintf(out, "    JSON field path (eg: field.sub-field).\n")
}

func main() {
	flag.Usage = usage
	url := flag.String("url", "", "URL to fetch every second. Read JSON objects from stdin if not specified.")
	interval := flag.Duration("interval", time.Second, "When url is provided, defines the interval between fetches."+
		" Note that counter fields are computed based on this interval.")
	steps := flag.Int("steps", 100, "Number of values to plot.")
	rows := flag.Int("rows", 0, "Limits the height of the graph output.")
	flag.Parse()

	if !term.HasGraphics() {
		fatal("iTerm2, Kitty, or DRCS Sixel graphics required")
	}

	if len(flag.Args()) == 0 {
		flag.Usage()
		os.Exit(1)
	}

	specs, err := data.ParseSpec(flag.Args())
	if err != nil {
		fatal("Cannot parse spec: ", err)
	}

	onError := func(err error) {
		fatal("Data source error: ", err)
	}
	var dp *data.Points
	if *url != "" {
		dp = data.FromHTTP(*url, *interval, specs, *steps, onError)
	} else if term.IsTerminal(os.Stdin) {
		fatal("neither --url nor stdin is provided")
	} else {
		dp = data.FromReader(os.Stdin, specs, *steps, onError)
	}

	sigs := make(chan os.Signal, 1)
	signal.Notify(sigs, os.Interrupt, syscall.SIGTERM)
	go func() {
		<-sigs
		signal.Reset(os.Interrupt, syscall.SIGTERM)
		dp.Close()
	}()

	dash := graph.Dash{Specs: specs, Data: dp}

	wg := &sync.WaitGroup{}
	wg.Add(1)
	go func() {
		defer wg.Done()
		t := time.NewTicker(time.Second)
		defer t.Stop()
		i := 0
		for {
			select {
			case <-t.C:
				if i == 0 {
					r := prepare(*rows)
					defer cleanup(r)
				}
				i++
				saveCursor()
				render(dash, *rows)
				restoreCursor()
			case <-dp.Done():
				if i == 0 {
					render(dash, *rows)
				}
				return
			}
		}
	}()
	wg.Wait()
}

func fatal(a ...interface{}) {
	fmt.Println(append([]interface{}{"jplot: "}, a...)...)
	os.Exit(1)
}

func prepare(rows int) int {
	os.Stderr.WriteString("\033[?25l")
	if rows == 0 {
		var err error
		if rows, err = term.Rows(); err != nil {
			fatal("Cannot get window size: ", err)
		}
	}
	os.Stderr.WriteString(strings.Repeat("\n", rows))
	fmt.Printf("\033[%dA", rows)
	return rows
}

func cleanup(rows int) {
	os.Stderr.WriteString("\033[?25h")
	fmt.Printf("\033[%dB", rows)
	os.Stderr.WriteString("\n")
}

func saveCursor() {
	os.Stderr.WriteString("\033[s")
}

func restoreCursor() {
	os.Stderr.WriteString("\033[u")
}

func render(dash graph.Dash, rows int) {
	size, err := term.Size()
	if err != nil {
		fatal("Cannot get window size: ", err)
	}
	width, height := size.Width, size.Height
	if rows > 0 {
		height = size.Height / size.Row * rows
	}
	w := term.NewImageWriter(width, height)
	defer w.Close()
	if err := dash.Render(w, width, height); err != nil {
		fatal(fmt.Errorf("cannot render graph: %v", err))
	}
}
EOF
echo ok"}

