package main

// Simple OCR for jplot axis labels.
// usage: ocr2 train img x0 y0 x1 y1 "text"   -> appends templates to /tmp/tools/ocr2/templates.txt
//        ocr2 read img x0 y0 x1 y1           -> prints recognized text lines (blocks separated by blank rows)
import (
	"bufio"
	"fmt"
	"image"
	"image/png"
	"os"
	"strconv"
	"strings"
)

type glyph struct {
	w, h int
	bits []bool
	x    int
}

func load(fn string) *image.NRGBA {
	f, _ := os.Open(fn)
	im, err := png.Decode(f)
	if err != nil {
		panic(err)
	}
	return im.(*image.NRGBA)
}

func ink(img *image.NRGBA, x, y int, white bool) bool {
	c := img.NRGBAAt(x, y)
	if white {
		return c.R > 200 && c.G > 200 && c.B > 200
	}
	return c.A > 110 && c.R == c.G && c.G == c.B && c.R > 150
}

// segment a text line (rows y0..y1) into glyphs
func segment(img *image.NRGBA, x0, y0, x1, y1 int, white bool) []glyph {
	var gs []glyph
	x := x0
	for x < x1 {
		has := func(x int) bool {
			for y := y0; y < y1; y++ {
				if ink(img, x, y, white) {
					return true
				}
			}
			return false
		}
		for x < x1 && !has(x) {
			x++
		}
		if x >= x1 {
			break
		}
		s := x
		for x < x1 && has(x) {
			x++
		}
		e := x
		// vertical bounds
		top, bot := y1, y0
		for yy := y0; yy < y1; yy++ {
			for xx := s; xx < e; xx++ {
				if ink(img, xx, yy, white) {
					if yy < top {
						top = yy
					}
					if yy > bot {
						bot = yy
					}
				}
			}
		}
		g := glyph{w: e - s, h: bot - top + 1, x: s}
		// encode relative to the line baseline region: keep top offset
		g.bits = make([]bool, 0)
		for yy := y0; yy < y1; yy++ {
			for xx := s; xx < e; xx++ {
				g.bits = append(g.bits, ink(img, xx, yy, white))
			}
		}
		g.h = y1 - y0
		gs = append(gs, g)
	}
	return gs
}

func key(g glyph) string {
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("%d %d ", g.w, g.h))
	for _, b := range g.bits {
		if b {
			sb.WriteByte('1')
		} else {
			sb.WriteByte('0')
		}
	}
	return sb.String()
}

type tmpl struct {
	ch   string
	w, h int
	bits string
}

func loadT() []tmpl {
	f, err := os.Open("/tmp/tools/ocr2/templates.txt")
	if err != nil {
		return nil
	}
	defer f.Close()
	var ts []tmpl
	s := bufio.NewScanner(f)
	s.Buffer(make([]byte, 1<<20), 1<<20)
	for s.Scan() {
		p := strings.SplitN(s.Text(), " ", 4)
		w, _ := strconv.Atoi(p[1])
		h, _ := strconv.Atoi(p[2])
		ts = append(ts, tmpl{p[0], w, h, p[3]})
	}
	return ts
}

func match(ts []tmpl, g glyph) string {
	best, bd := "?", 1<<30
	k := key(g)
	bits := k[strings.LastIndex(k, " ")+1:]
	for _, t := range ts {
		if t.h != g.h {
			continue
		}
		// compare with horizontal alignment tolerance
		d := 0
		if t.w == g.w {
			for i := range bits {
				if bits[i] != t.bits[i] {
					d++
				}
			}
		} else {
			d = 1000 + 10*abs(t.w-g.w)
			if abs(t.w-g.w) <= 1 {
				// compare overlapping columns
				mw := t.w
				if g.w < mw {
					mw = g.w
				}
				dd := 0
				for y := 0; y < g.h; y++ {
					for x := 0; x < mw; x++ {
						if bits[y*g.w+x] != t.bits[y*t.w+x] {
							dd++
						}
					}
				}
				d = dd + 3*abs(t.w-g.w)*g.h/2
			}
		}
		if d < bd {
			bd, best = d, t.ch
		}
	}
	return best
}

func abs(a int) int {
	if a < 0 {
		return -a
	}
	return a
}

func main() {
	mode := os.Args[1]
	img := load(os.Args[2])
	x0, _ := strconv.Atoi(os.Args[3])
	y0, _ := strconv.Atoi(os.Args[4])
