		return
	}
	ts := loadT()
	// read: find text lines (blocks of rows with ink)
	rowHas := func(y int) bool {
		for x := x0; x < x1; x++ {
			if ink(img, x, y, white) {
				return true
			}
		}
		return false
	}
	y := y0
	for y < y1 {
		for y < y1 && !rowHas(y) {
			y++
		}
		if y >= y1 {
			break
		}
		s := y
		for y < y1 && rowHas(y) {
			y++
		}
		// normalize to a fixed height window: use s-1 .. s+12
		top := s - 1
		gs := segment(img, x0, top, x1, top+13, white)
		out := ""
		lastx := -100
		for _, g := range gs {
			if lastx >= 0 && g.x-lastx > 7 {
				out += " "
			}
			out += match(ts, g)
			lastx = g.x + g.w
		}
		fmt.Printf("y=%d..%d: %s\n", s, y-1, out)
	}
}
