// Package font implements a minimal TrueType parser able to produce glyph
// outlines for rendering.
package font

import (
	_ "embed"
	"encoding/binary"
	"errors"
)

//go:embed DejaVuSans.ttf
var dejaVuSans []byte

// Point is a point of a glyph outline in font units (y up).
type Point struct {
	X, Y float64
}

// Contour is a closed outline made of line segments.
type Contour []Point

// Font is a parsed TrueType font.
type Font struct {
	data        []byte
	unitsPerEm  float64
	locFormat   int
	numGlyphs   int
	numHMetrics int
	ascent      float64
	descent     float64
	tables      map[string][]byte
	cmap        map[rune]int
	cache       map[int]*Glyph
}

// Glyph holds the outline and metrics of a glyph.
type Glyph struct {
	Advance  float64
	Contours []Contour
}

// Default returns the embedded font.
func Default() *Font {
	if defaultFont == nil {
		f, err := Parse(dejaVuSans)
		if err != nil {
			panic(err)
		}
		defaultFont = f
	}
	return defaultFont
}

var defaultFont *Font

func u16(b []byte, off int) int { return int(binary.BigEndian.Uint16(b[off:])) }
func i16(b []byte, off int) int { return int(int16(binary.BigEndian.Uint16(b[off:]))) }
func u32(b []byte, off int) int { return int(binary.BigEndian.Uint32(b[off:])) }

// Parse parses a TrueType font file.
func Parse(data []byte) (*Font, error) {
	if len(data) < 12 {
		return nil, errors.New("font: too short")
	}
	f := &Font{data: data, tables: map[string][]byte{}, cmap: map[rune]int{}, cache: map[int]*Glyph{}}
	n := u16(data, 4)
	for i := 0; i < n; i++ {
		rec := 12 + 16*i
		tag := string(data[rec : rec+4])
		off := u32(data, rec+8)
		ln := u32(data, rec+12)
		if off+ln > len(data) {
			return nil, errors.New("font: bad table")
		}
		f.tables[tag] = data[off : off+ln]
	}
	head := f.tables["head"]
	hhea := f.tables["hhea"]
	maxp := f.tables["maxp"]
	if head == nil || hhea == nil || maxp == nil || f.tables["glyf"] == nil || f.tables["loca"] == nil {
		return nil, errors.New("font: missing tables")
	}
	f.unitsPerEm = float64(u16(head, 18))
	f.locFormat = i16(head, 50)
	f.numGlyphs = u16(maxp, 4)
	f.ascent = float64(i16(hhea, 4))
	f.descent = float64(i16(hhea, 6))
	f.numHMetrics = u16(hhea, 34)
	f.parseCmap()
	return f, nil
}

func (f *Font) parseCmap() {
	c := f.tables["cmap"]
	if c == nil {
		return
	}
	n := u16(c, 2)
	best := -1
	for i := 0; i < n; i++ {
		pid := u16(c, 4+8*i)
		eid := u16(c, 4+8*i+2)
		off := u32(c, 4+8*i+4)
		if (pid == 3 && eid == 1) || pid == 0 {
			if u16(c, off) == 4 {
				best = off
				break
			}
		}
	}
	if best < 0 {
		return
	}
	t := c[best:]
	segX2 := u16(t, 6)
	segs := segX2 / 2
	ends := 14
	starts := ends + segX2 + 2
	deltas := starts + segX2
	ranges := deltas + segX2
	for s := 0; s < segs; s++ {
		end := u16(t, ends+2*s)
		start := u16(t, starts+2*s)
		delta := i16(t, deltas+2*s)
		ro := u16(t, ranges+2*s)
		if start > 0x7f && start > 0x2000 {
			// only the ranges actually needed are decoded lazily below
		}
		for ch := start; ch <= end && ch != 0xffff; ch++ {
			var g int
			if ro == 0 {
				g = (ch + delta) & 0xffff
			} else {
				idx := ranges + 2*s + ro + 2*(ch-start)
				if idx+2 > len(t) {
					continue
				}
				g = u16(t, idx)
				if g != 0 {
					g = (g + delta) & 0xffff
				}
			}
			if g != 0 {
				f.cmap[rune(ch)] = g
			}
		}
	}
}

// Index returns the glyph index of r.
func (f *Font) Index(r rune) int {
	return f.cmap[r]
}

// UnitsPerEm returns the font design units per em.
func (f *Font) UnitsPerEm() float64 { return f.unitsPerEm }

// Ascent returns the typographic ascent in font units.
func (f *Font) Ascent() float64 { return f.ascent }

// Descent returns the typographic descent in font units (negative).
func (f *Font) Descent() float64 { return f.descent }

func (f *Font) advance(g int) float64 {
	hmtx := f.tables["hmtx"]
	if g >= f.numHMetrics {
		g = f.numHMetrics - 1
	}
	if hmtx == nil || 4*g+2 > len(hmtx) {
		return 0
	}
	return float64(u16(hmtx, 4*g))
}

func (f *Font) glyphData(g int) []byte {
	loca := f.tables["loca"]
	glyf := f.tables["glyf"]
	if g < 0 || g >= f.numGlyphs {
		return nil
	}
	var start, end int
	if f.locFormat == 0 {
		start = 2 * u16(loca, 2*g)
		end = 2 * u16(loca, 2*g+2)
	} else {
		start = u32(loca, 4*g)
		end = u32(loca, 4*g+4)
	}
	if start >= end || end > len(glyf) {
		return nil
	}
	return glyf[start:end]
}

// Glyph returns the glyph with the given index.
func (f *Font) Glyph(g int) *Glyph {
	if gl, ok := f.cache[g]; ok {
		return gl
	}
	gl := &Glyph{Advance: f.advance(g)}
	gl.Contours = f.outline(g, 0)
	f.cache[g] = gl
	return gl
}

type rawPoint struct {
	x, y float64
	on   bool
}

func (f *Font) outline(g int, depth int) []Contour {
	b := f.glyphData(g)
	if b == nil || depth > 8 {
		return nil
	}
	nc := i16(b, 0)
	if nc < 0 {
		return f.composite(b, depth)
	}
	p := 10
	endPts := make([]int, nc)
	for i := 0; i < nc; i++ {
		endPts[i] = u16(b, p)
		p += 2
	}
	if nc == 0 {
		return nil
	}
	np := endPts[nc-1] + 1
	insLen := u16(b, p)
	p += 2 + insLen
	flags := make([]byte, np)
	for i := 0; i < np; {
		fl := b[p]
		p++
		flags[i] = fl
		i++
		if fl&8 != 0 {
			rep := int(b[p])
			p++
			for k := 0; k < rep && i < np; k++ {
				flags[i] = fl
				i++
			}
		}
	}
	pts := make([]rawPoint, np)
	x := 0
	for i := 0; i < np; i++ {
		fl := flags[i]
		if fl&2 != 0 {
			dx := int(b[p])
			p++
			if fl&16 == 0 {
				dx = -dx
			}
			x += dx
		} else if fl&16 == 0 {
			x += i16(b, p)
			p += 2
		}
		pts[i].x = float64(x)
		pts[i].on = fl&1 != 0
	}
	y := 0
	for i := 0; i < np; i++ {
		fl := flags[i]
		if fl&4 != 0 {
			dy := int(b[p])
			p++
			if fl&32 == 0 {
				dy = -dy
			}
			y += dy
		} else if fl&32 == 0 {
			y += i16(b, p)
			p += 2
		}
		pts[i].y = float64(y)
	}
	var out []Contour
	start := 0
	for _, e := range endPts {
		out = append(out, flatten(pts[start:e+1]))
		start = e + 1
	}
	return out
}

func (f *Font) composite(b []byte, depth int) []Contour {
	var out []Contour
	p := 10
	for {
		flags := u16(b, p)
		gi := u16(b, p+2)
		p += 4
		var dx, dy float64
		if flags&1 != 0 {
			dx = float64(i16(b, p))
			dy = float64(i16(b, p+2))
			p += 4
		} else {
			dx = float64(int8(b[p]))
			dy = float64(int8(b[p+1]))
			p += 2
		}
		a, bb, c, d := 1.0, 0.0, 0.0, 1.0
		switch {
		case flags&8 != 0:
			a = float64(i16(b, p)) / 16384
			d = a
			p += 2
		case flags&0x40 != 0:
			a = float64(i16(b, p)) / 16384
			d = float64(i16(b, p+2)) / 16384
			p += 4
		case flags&0x80 != 0:
			a = float64(i16(b, p)) / 16384
			bb = float64(i16(b, p+2)) / 16384
			c = float64(i16(b, p+4)) / 16384
			d = float64(i16(b, p+6)) / 16384
			p += 8
		}
		for _, ct := range f.outline(gi, depth+1) {
			nc := make(Contour, len(ct))
			for i, pt := range ct {
				nc[i] = Point{a*pt.X + c*pt.Y + dx, bb*pt.X + d*pt.Y + dy}
			}
			out = append(out, nc)
		}
		if flags&0x20 == 0 {
			break
		}
	}
	return out
}

// flatten converts a quadratic TrueType contour into line segments.
func flatten(pts []rawPoint) Contour {
	n := len(pts)
	if n == 0 {
		return nil
	}
	// find a starting on-curve point
	startIdx := -1
	for i, p := range pts {
		if p.on {
			startIdx = i
			break
		}
	}
	var start Point
	if startIdx < 0 {
		start = Point{(pts[0].x + pts[1%n].x) / 2, (pts[0].y + pts[1%n].y) / 2}
		startIdx = 0
	} else {
		start = Point{pts[startIdx].x, pts[startIdx].y}
		startIdx++
	}
	out := Contour{start}
	cur := start
	var ctrl *Point
	for k := 0; k < n; k++ {
		p := pts[(startIdx+k)%n]
		pt := Point{p.x, p.y}
		if p.on {
			if ctrl != nil {
				out = appendQuad(out, cur, *ctrl, pt)
				ctrl = nil
			} else {
				out = append(out, pt)
			}
			cur = pt
		} else {
			if ctrl != nil {
				mid := Point{(ctrl.X + pt.X) / 2, (ctrl.Y + pt.Y) / 2}
				out = appendQuad(out, cur, *ctrl, mid)
				cur = mid
			}
			c := pt
			ctrl = &c
		}
	}
	if ctrl != nil {
		out = appendQuad(out, cur, *ctrl, start)
	}
	return out
}

func appendQuad(out Contour, p0, c, p1 Point) Contour {
	const steps = 8
	for i := 1; i <= steps; i++ {
		t := float64(i) / steps
		u := 1 - t
		out = append(out, Point{
			u*u*p0.X + 2*u*t*c.X + t*t*p1.X,
			u*u*p0.Y + 2*u*t*c.Y + t*t*p1.Y,
		})
	}
	return out
}
