package graph

import (
	"image"
	"image/color"
	"math"
)

type point struct{ X, Y float64 }

// polygon is a closed list of points.
type polygon []point

// canvas wraps an RGBA image with anti-aliased drawing primitives.
type canvas struct {
	img  *image.RGBA
	w, h int
}

func newCanvas(img *image.RGBA) *canvas {
	b := img.Bounds()
	return &canvas{img: img, w: b.Dx(), h: b.Dy()}
}

// raster accumulates signed area coverage for a region of the canvas.
type raster struct {
	ox, oy int
	w, h   int
	acc    []float32
}

func newRaster(ox, oy, w, h int) *raster {
	return &raster{ox: ox, oy: oy, w: w, h: h, acc: make([]float32, (w+2)*h)}
}

// line adds the contribution of the segment p0-p1 (canvas coordinates).
func (r *raster) line(p0, p1 point) {
	x0, y0 := p0.X-float64(r.ox), p0.Y-float64(r.oy)
	x1, y1 := p1.X-float64(r.ox), p1.Y-float64(r.oy)
	// clip horizontally by splitting the segment at the region borders.
	W := float64(r.w)
	clipX := func(a, b point) {
		r.lineLocal(a, b)
	}
	segs := splitX(point{x0, y0}, point{x1, y1}, 0)
	for _, s := range segs {
		for _, t := range splitX(s[0], s[1], W) {
			a, b := t[0], t[1]
			if a.X < 0 && b.X <= 0 || a.X <= 0 && b.X < 0 {
				a.X, b.X = 0, 0
			}
			if a.X > W && b.X >= W || a.X >= W && b.X > W {
				a.X, b.X = W, W
			}
			clipX(a, b)
		}
	}
}

func splitX(a, b point, x float64) [][2]point {
	if (a.X < x && b.X > x) || (a.X > x && b.X < x) {
		t := (x - a.X) / (b.X - a.X)
		m := point{x, a.Y + t*(b.Y-a.Y)}
		return [][2]point{{a, m}, {m, b}}
	}
	return [][2]point{{a, b}}
}

func (r *raster) lineLocal(p0, p1 point) {
	if p0.Y == p1.Y {
		return
	}
	dir := float32(1)
	if p0.Y > p1.Y {
		dir = -1
		p0, p1 = p1, p0
	}
	dxdy := (p1.X - p0.X) / (p1.Y - p0.Y)
	x := p0.X
	if p0.Y < 0 {
		x -= p0.Y * dxdy
	}
	stride := r.w + 2
	ystart := int(math.Max(0, math.Floor(p0.Y)))
	yend := int(math.Min(float64(r.h), math.Ceil(p1.Y)))
	for y := ystart; y < yend; y++ {
		line := y * stride
		dy := math.Min(float64(y+1), p1.Y) - math.Max(float64(y), p0.Y)
		xnext := x + dxdy*dy
		d := float32(dy) * dir
		xa, xb := x, xnext
		if xa > xb {
			xa, xb = xb, xa
		}
		xaf := math.Floor(xa)
		xai := int(xaf)
		xbc := math.Ceil(xb)
		xbi := int(xbc)
		if xai < 0 {
			xai = 0
		}
		if xbi <= xai+1 {
			xmf := float32(0.5*(x+xnext) - xaf)
			r.add(line+xai, d-d*xmf)
			r.add(line+xai+1, d*xmf)
		} else {
			s := float32(1 / (xb - xa))
			x0f := float32(xa - xaf)
			a0 := 0.5 * s * (1 - x0f) * (1 - x0f)
			x1f := float32(xb - xbc + 1)
			am := 0.5 * s * x1f * x1f
			r.add(line+xai, d*a0)
			if xbi == xai+2 {
				r.add(line+xai+1, d*(1-a0-am))
			} else {
				a1 := s * (1.5 - x0f)
				r.add(line+xai+1, d*(a1-a0))
				for xi := xai + 2; xi < xbi-1; xi++ {
					r.add(line+xi, d*s)
				}
				a2 := a1 + float32(xbi-xai-3)*s
				r.add(line+xbi-1, d*(1-a2-am))
			}
			r.add(line+xbi, d*am)
		}
		x = xnext
	}
}

func (r *raster) add(i int, v float32) {
	if i >= 0 && i < len(r.acc) {
		r.acc[i] += v
	}
}

func (r *raster) polygon(p polygon) {
	n := len(p)
	for i := 0; i < n; i++ {
		r.line(p[i], p[(i+1)%n])
	}
}

// fill composites the accumulated coverage onto the canvas with color c.
func (c *canvas) composite(r *raster, col color.NRGBA) {
	stride := r.w + 2
	ca := float32(col.A) / 255
	for y := 0; y < r.h; y++ {
		var acc float32
		py := r.oy + y
		for x := 0; x < r.w; x++ {
			acc += r.acc[y*stride+x]
			cov := acc
			if cov < 0 {
				cov = -cov
			}
			if cov > 1 {
				cov = 1
			}
			if cov < 1.0/512 {
				continue
			}
			px := r.ox + x
			c.blend(px, py, col, cov*ca)
		}
	}
}

func (c *canvas) blend(x, y int, col color.NRGBA, a float32) {
	i := c.img.PixOffset(x, y)
	pix := c.img.Pix[i : i+4 : i+4]
	ia := 1 - a
	pix[0] = uint8(float32(col.R)*a + float32(pix[0])*ia + 0.5)
	pix[1] = uint8(float32(col.G)*a + float32(pix[1])*ia + 0.5)
	pix[2] = uint8(float32(col.B)*a + float32(pix[2])*ia + 0.5)
	pix[3] = uint8(255*a + float32(pix[3])*ia + 0.5)
}

// regionFor returns a raster covering the bounding box of the given
// polygons, clipped to the canvas (and optional clip rectangle).
func (c *canvas) regionFor(clip image.Rectangle, polys ...polygon) *raster {
	minx, miny := math.Inf(1), math.Inf(1)
	maxx, maxy := math.Inf(-1), math.Inf(-1)
	for _, p := range polys {
		for _, q := range p {
			minx = math.Min(minx, q.X)
			miny = math.Min(miny, q.Y)
			maxx = math.Max(maxx, q.X)
			maxy = math.Max(maxy, q.Y)
		}
	}
	if math.IsInf(minx, 0) {
		return nil
	}
	rect := image.Rect(int(math.Floor(minx)), int(math.Floor(miny)), int(math.Ceil(maxx))+1, int(math.Ceil(maxy))+1)
	rect = rect.Intersect(image.Rect(0, 0, c.w, c.h)).Intersect(clip)
	if rect.Empty() {
		return nil
	}
	return newRaster(rect.Min.X, rect.Min.Y, rect.Dx(), rect.Dy())
}

// fillPolys fills the union of the given polygons.
func (c *canvas) fillPolys(clip image.Rectangle, col color.NRGBA, polys ...polygon) {
	if col.A == 0 {
		return
	}
	r := c.regionFor(clip, polys...)
	if r == nil {
		return
	}
	for _, p := range polys {
		r.polygon(p)
	}
	c.composite(r, col)
}

func (c *canvas) bounds() image.Rectangle { return image.Rect(0, 0, c.w, c.h) }

// strokePolys returns the polygons approximating a stroked polyline.
func strokePolys(pts []point, width float64, joins bool) []polygon {
	var out []polygon
	hw := width / 2
	for i := 0; i+1 < len(pts); i++ {
		a, b := pts[i], pts[i+1]
		dx, dy := b.X-a.X, b.Y-a.Y
		l := math.Hypot(dx, dy)
		if l == 0 {
			continue
		}
		nx, ny := -dy/l*hw, dx/l*hw
		out = append(out, polygon{
			{a.X + nx, a.Y + ny},
			{b.X + nx, b.Y + ny},
			{b.X - nx, b.Y - ny},
			{a.X - nx, a.Y - ny},
		})
	}
	if joins && hw > 0.6 {
		for i := 1; i+1 < len(pts); i++ {
			out = append(out, circle(pts[i], hw))
		}
	}
	return out
}

func circle(c point, r float64) polygon {
	const n = 12
	p := make(polygon, n)
	for i := 0; i < n; i++ {
		// orientation matching the stroke rectangles
		a := -2 * math.Pi * float64(i) / n
		p[i] = point{c.X + r*math.Cos(a), c.Y + r*math.Sin(a)}
	}
	return p
}

// strokeLine draws a polyline.
func (c *canvas) strokeLine(clip image.Rectangle, col color.NRGBA, width float64, pts ...point) {
	c.fillPolys(clip, col, strokePolys(pts, width, true)...)
}

// rect returns an axis aligned rectangle polygon.
func rect(x0, y0, x1, y1 float64) polygon {
	return polygon{{x0, y0}, {x1, y0}, {x1, y1}, {x0, y1}}
}
