package graph

import (
	"math"
	"strconv"
	"strings"
)

var siPrefixes = []struct {
	exp    int
	prefix string
}{
	{24, "Y"}, {21, "Z"}, {18, "E"}, {15, "P"}, {12, "T"}, {9, "G"}, {6, "M"}, {3, "k"},
	{0, ""},
	{-3, "m"}, {-6, "µ"}, {-9, "n"}, {-12, "p"}, {-15, "f"}, {-18, "a"}, {-21, "z"}, {-24, "y"},
}

// siScale returns the exponent (multiple of 3) to use for v.
func siScale(v float64) int {
	a := math.Abs(v)
	if a == 0 || math.IsNaN(a) || math.IsInf(a, 0) {
		return 0
	}
	for _, p := range siPrefixes {
		if a >= math.Pow(10, float64(p.exp)) {
			return p.exp
		}
	}
	return siPrefixes[len(siPrefixes)-1].exp
}

func siPrefix(exp int) string {
	for _, p := range siPrefixes {
		if p.exp == exp {
			return p.prefix
		}
	}
	return ""
}

func trimZeros(s string) string {
	if strings.Contains(s, ".") {
		s = strings.TrimRight(s, "0")
		s = strings.TrimSuffix(s, ".")
	}
	if s == "-0" {
		s = "0"
	}
	return s
}

// humanValue formats v using SI prefixes keeping at most two decimals
// (truncated).
func humanValue(v float64) string {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return strconv.FormatFloat(v, 'f', -1, 64)
	}
	exp := siScale(v)
	s := v / math.Pow(10, float64(exp))
	s = math.Trunc(s*100+1e-9*math.Copysign(1, s)) / 100
	return trimZeros(strconv.FormatFloat(s, 'f', 2, 64)) + siPrefix(exp)
}

// tickResolution returns the rounding resolution exponent for a tick step.
func tickResolution(step float64) int {
	if step <= 0 || math.IsNaN(step) || math.IsInf(step, 0) {
		return 0
	}
	return int(math.Floor(math.Log10(step))) - 1
}

// ceilTo rounds v up to a multiple of 10^res.
func ceilTo(v float64, res int) float64 {
	p := math.Pow(10, float64(-res))
	r := math.Ceil(v*p-1e-9) / p
	if r == 0 {
		return 0
	}
	return r
}

// yTickLabel formats an axis tick value.
func yTickLabel(v float64, res int) string {
	v = ceilTo(v, res)
	exp := siScale(v)
	s := v / math.Pow(10, float64(exp))
	prec := exp - res
	if prec < 0 {
		prec = 0
	}
	if prec > 6 {
		prec = 6
	}
	return trimZeros(strconv.FormatFloat(s, 'f', prec, 64)) + siPrefix(exp)
}

// xTickLabel formats an x axis tick value.
func xTickLabel(v float64, res int) string {
	return strconv.FormatFloat(ceilTo(v, res), 'f', 2, 64)
}
