package graph

import (
	"image"
	"image/color"

	"jplot/graph/font"
)

// face renders text using the embedded font.
type face struct {
	f      *font.Font
	size   float64 // em size in pixels
	xscale float64
}

func newFace(size float64) face {
	return face{f: font.Default(), size: size, xscale: 0.88}
}

func (fc face) scale() float64 { return fc.size / fc.f.UnitsPerEm() }

// width returns the advance width of s in pixels.
func (fc face) width(s string) float64 {
	w := 0.0
	for _, r := range s {
		g := fc.f.Glyph(fc.f.Index(r))
		w += g.Advance * fc.scale() * fc.xscale
	}
	return w
}

// capHeight returns the height of digits in pixels.
func (fc face) capHeight() float64 {
	return 0.729 * fc.size
}

// draw renders s with its baseline starting at (x, y).
func (fc face) draw(c *canvas, clip image.Rectangle, x, y float64, col color.NRGBA, s string) {
	sc := fc.scale()
	var polys []polygon
	for _, r := range s {
		g := fc.f.Glyph(fc.f.Index(r))
		for _, ct := range g.Contours {
			p := make(polygon, len(ct))
			for i, pt := range ct {
				p[i] = point{x + pt.X*sc*fc.xscale, y - pt.Y*sc}
			}
			polys = append(polys, p)
		}
		x += g.Advance * sc * fc.xscale
	}
	if len(polys) > 0 {
		c.fillPolys(clip, col, polys...)
	}
}
