import os, pty, sys, struct, fcntl, termios, select, time, subprocess, signal, re, base64, threading, json
ORIG='/workspace/executable'
MINE=os.environ.get('MINE','/tmp/jplot_mine')

def run(binary, args, rows=24, cols=80, xp=0, yp=0, resp=None, feed=None, env=None, tmo=4, fds='0=pipe,1=tty,2=tty', events=None):
    m, s = pty.openpty()
    fcntl.ioctl(s, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, xp, yp))
    e=dict(os.environ); e.pop('TERM_PROGRAM', None)
    if env: e.update(env)
    fd = dict(kv.split('=') for kv in fds.split(','))
    def pick(i):
        v=fd[str(i)]
        return s if v=='tty' else subprocess.PIPE
    p = subprocess.Popen([binary]+args, stdin=pick(0), stdout=pick(1), stderr=pick(2), env=e)
    os.close(s)
    pipes={}
    def rd(name,f): pipes[name]=f.read()
    ths=[]
    for name,f in (('out',p.stdout),('err',p.stderr)):
        if f:
            t=threading.Thread(target=rd,args=(name,f)); t.start(); ths.append(t)
    feed = list(feed or [])
    def feeder():
        for item in feed:
            if isinstance(item,(int,float)): time.sleep(item)
            else:
                try: p.stdin.write(item); p.stdin.flush()
                except Exception: return
        try: p.stdin.close()
        except Exception: pass
    if p.stdin:
        ft=threading.Thread(target=feeder); ft.start()
    start=time.time(); out=b''
    evs=sorted(events or [])
    while time.time()-start < tmo:
        now=time.time()-start
        while evs and evs[0][0] <= now:
            t,sig=evs.pop(0); p.send_signal(sig)
        r,_,_=select.select([m],[],[],0.02)
        if r:
            try: d=os.read(m,65536)
            except OSError: break
            if not d: break
            out+=d
            if resp:
                for q,a in resp:
                    if q in d: os.write(m,a)
        if p.poll() is not None and not r:
            while True:
                r,_,_=select.select([m],[],[],0.2)
                if not r: break
                try: d=os.read(m,65536)
                except OSError: break
                if not d: break
                out+=d
            break
    if p.poll() is None:
        p.kill(); p.wait()
    for t in ths: t.join(2)
    return p.returncode, out, pipes.get('out',b''), pipes.get('err',b'')

def summarize(b):
    def it(mm):
        data=mm.group(2)
        try:
            png=base64.b64decode(data+b'='*((-len(data))%4))
            w,h=struct.unpack('>II',png[16:24]) if len(png)>=24 else (0,0)
        except Exception:
            w=h=-1
        return b'<ITERM ' + mm.group(1) + b' png=%dx%d b64mod3=%d>' % (w,h,len(data)%4)
    b=re.sub(rb'\x1b\]1337;File=([^:]*):([A-Za-z0-9+/=]*)\x07', it, b)
    def kt(mm):
        data=mm.group(2)
        try:
            png=base64.b64decode(data)
            w,h=struct.unpack('>II',png[16:24]) if len(png)>=24 else (0,0)
        except Exception:
            w=h=-1
        return b'<KITTY ' + mm.group(1) + b' png=%dx%d pad=%d>' % (w,h,len(data)%4)
    b=re.sub(rb'\x1b_G(a=T[^;]*);([A-Za-z0-9+/=]*)\x1b\\\\', kt, b)
    def st(mm):
        body=mm.group(0)
        nb=body.count(b'-')
        return b'<SIXEL bands=%d>' % nb
    b=re.sub(rb'\x1bP0;0;8q.*?\x1b\\\\', st, b, flags=re.S)
    b=re.sub(rb'goroutine \d+', b'goroutine N', b)
    b=re.sub(rb'(panic: [^\n\r]*)[\s\S]*', rb'\1 <trace>', b)
    return b

def compare(name, args, **kw):
    ro=run(ORIG,args,**kw); rm=run(MINE,args,**kw)
    so=[ro[0]]+[summarize(x) for x in ro[1:]]
    sm=[rm[0]]+[summarize(x) for x in rm[1:]]
    ok = so==sm
    print(('OK  ' if ok else 'DIFF'), name)
    if not ok:
        for lab,a,b in zip(['rc','tty','out','err'],so,sm):
            if a!=b:
                print('   ',lab,'orig:',repr(a)[:600])
                print('   ',lab,'mine:',repr(b)[:600])
    return ok
EOF
